def untested(requirements, tests):
    covered, failing = set(), set()
    for t in tests:
        for rid in t['covers']:
            if rid in requirements:
                covered.add(rid)
                if t['status'] == 'fail':
                    failing.add(rid)
    return {'no_evidence': sorted(set(requirements) - covered), 'failing': sorted(failing)}
